{
  "name": "CineFlow - Production Inventory Manager",
  "description": "A high-end equipment tracking and inventory management system for film and video production crews. Featuring status tracking, automated check-outs, and an AI-powered production assistant.",
  "requestFramePermissions": ["camera"]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

-- 1. Tables Definition

-- Profiles table (linked to auth.users)
CREATE TABLE public.profiles (
  id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
  full_name TEXT NOT NULL,
  role TEXT DEFAULT 'crew' CHECK (role IN ('admin', 'crew')),
  avatar_url TEXT
);

-- Categories table
CREATE TABLE public.categories (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  icon TEXT
);

-- Productions table
CREATE TABLE public.productions (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL,
  location TEXT,
  start_date DATE,
  end_date DATE,
  status TEXT DEFAULT 'pre-production' CHECK (status IN ('pre-production', 'production', 'post-production', 'wrapped'))
);

-- Inventory Items table
CREATE TABLE public.inventory_items (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL,
  model TEXT,
  serial_number TEXT UNIQUE,
  category_id UUID REFERENCES public.categories(id),
  status TEXT DEFAULT 'available' CHECK (status IN ('available', 'checked_out', 'maintenance', 'lost')),
  current_production_id UUID REFERENCES public.productions(id),
  assigned_to_id UUID REFERENCES public.profiles(id),
  description TEXT,
  image_url TEXT,
  last_serviced_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Checkouts table
CREATE TABLE public.checkouts (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  item_id UUID REFERENCES public.inventory_items(id) NOT NULL,
  user_id UUID REFERENCES public.profiles(id) NOT NULL,
  production_id UUID REFERENCES public.productions(id),
  checked_out_at TIMESTAMPTZ DEFAULT now(),
  due_at TIMESTAMPTZ,
  returned_at TIMESTAMPTZ
);

-- Activity Logs table
CREATE TABLE public.activity_logs (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  item_id UUID REFERENCES public.inventory_items(id),
  user_id UUID REFERENCES public.profiles(id),
  action TEXT NOT NULL, -- e.g., 'checkout', 'return', 'status_change'
  details JSONB,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Row Level Security (RLS) Policies

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.productions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.checkouts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY;

-- Profiles: Anyone can view profiles, only user can update own, admin can update all
CREATE POLICY "Public profiles are viewable by everyone" ON public.profiles FOR SELECT USING (true);
CREATE POLICY "Users can update own profile" ON public.profiles FOR UPDATE USING (auth.uid() = id);

-- Categories: Read for all, admin manage
CREATE POLICY "Categories viewable by all" ON public.categories FOR SELECT USING (true);
CREATE POLICY "Admin manage categories" ON public.categories FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin')
);

-- Items: Read for all, crew can update status on checkout, admin manage
CREATE POLICY "Items viewable by all" ON public.inventory_items FOR SELECT USING (true);
CREATE POLICY "Admin manage items" ON public.inventory_items FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin')
);

-- Checkouts: Crew can see their own, admin see all
CREATE POLICY "Crew see own checkouts" ON public.checkouts FOR SELECT USING (
  auth.uid() = user_id OR EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin')
);
CREATE POLICY "Admin manage checkouts" ON public.checkouts FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin')
);

-- Log: All can view, only system/admin insert
CREATE POLICY "Logs viewable by all" ON public.activity_logs FOR SELECT USING (true);
CREATE POLICY "System/Admin insert logs" ON public.activity_logs FOR INSERT WITH CHECK (true);

export type Role = 'admin' | 'crew';
export type ItemStatus = 'available' | 'checked_out' | 'maintenance' | 'lost';
export type ProductionStatus = 'pre-production' | 'production' | 'post-production' | 'wrapped';

export interface Profile {
  id: string;
  full_name: string;
  role: Role;
  avatar_url?: string;
}

export interface Category {
  id: string;
  name: string;
  icon?: string;
}

export interface Production {
  id: string;
  name: string;
  location?: string;
  start_date: string;
  end_date: string;
  status: ProductionStatus;
}

export interface InventoryItem {
  id: string;
  name: string;
  model: string;
  serial_number: string;
  category_id: string;
  status: ItemStatus;
  current_production_id?: string;
  assigned_to_id?: string;
  description?: string;
  image_url?: string;
  last_serviced_at?: string;
  created_at: string;
  category?: Category;
  assigned_to?: Profile;
  production?: Production;
}

export interface Checkout {
  id: string;
  item_id: string;
  user_id: string;
  production_id?: string;
  checked_out_at: string;
  due_at?: string;
  returned_at?: string;
  item?: InventoryItem;
  user?: Profile;
}

export interface ActivityLog {
  id: string;
  item_id?: string;
  user_id?: string;
  action: string;
  details?: any;
  created_at: string;
  item?: InventoryItem;
  user?: Profile;
}

import { InventoryItem, Category, Profile, Production, ActivityLog, ItemStatus } from '../types';

// Mock Data
const MOCK_CATEGORIES: Category[] = [
  { id: '1', name: 'Cameras', icon: 'Camera' },
  { id: '2', name: 'Lenses', icon: 'Disc' },
  { id: '3', name: 'Lighting', icon: 'Sun' },
  { id: '4', name: 'Audio', icon: 'Mic' },
  { id: '5', name: 'Power', icon: 'Battery' },
];

const MOCK_PROFILES: Profile[] = [
  { id: 'u1', full_name: 'Alex Rivera', role: 'admin', avatar_url: 'https://picsum.photos/seed/alex/100/100' },
  { id: 'u2', full_name: 'Jordan Smith', role: 'crew', avatar_url: 'https://picsum.photos/seed/jordan/100/100' },
];

const MOCK_PRODUCTIONS: Production[] = [
  { id: 'p1', name: 'Midnight Streets', location: 'Downtown LA', start_date: '2024-05-01', end_date: '2024-05-15', status: 'production' },
  { id: 'p2', name: 'The Silent Cabin', location: 'Vermont', start_date: '2024-06-10', end_date: '2024-07-05', status: 'pre-production' },
];

let MOCK_ITEMS: InventoryItem[] = [
  { id: 'i1', name: 'ARRI Alexa Mini LF', model: 'Mini LF', serial_number: 'AX-1203', category_id: '1', status: 'checked_out', assigned_to_id: 'u2', current_production_id: 'p1', created_at: new Date().toISOString() },
  { id: 'i2', name: 'Sony FX6', model: 'ILME-FX6V', serial_number: 'SN-4055', category_id: '1', status: 'available', created_at: new Date().toISOString() },
  { id: 'i3', name: 'Cooke S4/i 35mm', model: 'S4/i', serial_number: 'CK-3501', category_id: '2', status: 'checked_out', assigned_to_id: 'u2', current_production_id: 'p1', created_at: new Date().toISOString() },
  { id: 'i4', name: 'Aputure 600d Pro', model: '600d Pro', serial_number: 'AP-6001', category_id: '3', status: 'available', created_at: new Date().toISOString() },
  { id: 'i5', name: 'Sennheiser MKH 416', model: 'MKH 416', serial_number: 'SH-4160', category_id: '4', status: 'maintenance', created_at: new Date().toISOString() },
];

let MOCK_LOGS: ActivityLog[] = [
  { id: 'l1', item_id: 'i1', user_id: 'u2', action: 'Checkout', created_at: new Date(Date.now() - 86400000).toISOString(), details: { production: 'Midnight Streets' } },
  { id: 'l2', item_id: 'i3', user_id: 'u2', action: 'Checkout', created_at: new Date(Date.now() - 43200000).toISOString(), details: { production: 'Midnight Streets' } },
];

export const mockSupabase = {
  items: {
    getAll: async () => {
      return MOCK_ITEMS.map(item => ({
        ...item,
        category: MOCK_CATEGORIES.find(c => c.id === item.category_id),
        assigned_to: MOCK_PROFILES.find(p => p.id === item.assigned_to_id),
        production: MOCK_PRODUCTIONS.find(p => p.id === item.current_production_id),
      }));
    },
    update: async (id: string, updates: Partial<InventoryItem>) => {
      MOCK_ITEMS = MOCK_ITEMS.map(i => i.id === id ? { ...i, ...updates } : i);
      return MOCK_ITEMS.find(i => i.id === id);
    },
    checkout: async (itemId: string, userId: string, prodId: string) => {
      const item = MOCK_ITEMS.find(i => i.id === itemId);
      if (item && item.status === 'available') {
        const updates: Partial<InventoryItem> = {
          status: 'checked_out',
          assigned_to_id: userId,
          current_production_id: prodId
        };
        MOCK_ITEMS = MOCK_ITEMS.map(i => i.id === itemId ? { ...i, ...updates } : i);
        const log: ActivityLog = {
          id: Math.random().toString(36).substr(2, 9),
          item_id: itemId,
          user_id: userId,
          action: 'Checkout',
          created_at: new Date().toISOString(),
          details: { production_id: prodId }
        };
        MOCK_LOGS = [log, ...MOCK_LOGS];
        return true;
      }
      return false;
    },
    return: async (itemId: string) => {
      const item = MOCK_ITEMS.find(i => i.id === itemId);
      if (item) {
        const log: ActivityLog = {
          id: Math.random().toString(36).substr(2, 9),
          item_id: itemId,
          user_id: item.assigned_to_id,
          action: 'Return',
          created_at: new Date().toISOString(),
        };
        MOCK_LOGS = [log, ...MOCK_LOGS];
        MOCK_ITEMS = MOCK_ITEMS.map(i => i.id === itemId ? { 
          ...i, 
          status: 'available', 
          assigned_to_id: undefined, 
          current_production_id: undefined 
        } : i);
        return true;
      }
      return false;
    }
  },
  categories: {
    getAll: async () => MOCK_CATEGORIES,
  },
  profiles: {
    getAll: async () => MOCK_PROFILES,
    getMe: async () => MOCK_PROFILES[0], // Simulated logged in user (Admin)
  },
  productions: {
    getAll: async () => MOCK_PRODUCTIONS,
  },
  logs: {
    getAll: async () => {
        return MOCK_LOGS.map(log => ({
            ...log,
            item: MOCK_ITEMS.find(i => i.id === log.item_id),
            user: MOCK_PROFILES.find(p => p.id === log.user_id),
        }));
    }
  }
};

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getEquipmentAdvice = async (sceneDescription: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Suggest a filming equipment list for the following scene: "${sceneDescription}". 
      Focus on camera choice, lens focal lengths, lighting style, and audio needs. 
      Format as a concise technical recommendation for a professional crew.`,
      config: {
        systemInstruction: "You are a world-class Cinematographer and Gaffer advising a film crew on equipment selection.",
      }
    });
    return response.text;
  } catch (error) {
    console.error("AI Advice Error:", error);
    return "Unable to get AI advice at this time. Please check your production plan manually.";
  }
};

import React, { useState, useEffect } from 'react';
import { 
    LayoutDashboard, 
    Box, 
    ClipboardList, 
    Users, 
    Settings, 
    Bell, 
    Search,
    Plus,
    Filter,
    LogOut,
    Sparkles,
    ChevronRight,
    Loader2
} from 'lucide-react';
import { mockSupabase } from './services/mockSupabase';
import { InventoryItem, Profile, Production, ActivityLog, Category } from './types';
import InventoryGrid from './components/InventoryGrid';
import ActivityFeed from './components/ActivityFeed';
import StatsOverview from './components/StatsOverview';
import AISidebar from './components/AISidebar';

const App: React.FC = () => {
    const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'productions' | 'logs'>('dashboard');
    const [items, setItems] = useState<InventoryItem[]>([]);
    const [user, setUser] = useState<Profile | null>(null);
    const [productions, setProductions] = useState<Production[]>([]);
    const [logs, setLogs] = useState<ActivityLog[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        const init = async () => {
            setLoading(true);
            const [fetchedItems, fetchedUser, fetchedProds, fetchedLogs, fetchedCats] = await Promise.all([
                mockSupabase.items.getAll(),
                mockSupabase.profiles.getMe(),
                mockSupabase.productions.getAll(),
                mockSupabase.logs.getAll(),
                mockSupabase.categories.getAll(),
            ]);
            setItems(fetchedItems);
            setUser(fetchedUser);
            setProductions(fetchedProds);
            setLogs(fetchedLogs);
            setCategories(fetchedCats);
            setLoading(false);
        };
        init();
    }, []);

    const refreshData = async () => {
        const fetchedItems = await mockSupabase.items.getAll();
        const fetchedLogs = await mockSupabase.logs.getAll();
        setItems(fetchedItems);
        setLogs(fetchedLogs);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-screen bg-slate-950 text-white">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-500" />
            </div>
        );
    }

    return (
        <div className="flex h-screen bg-slate-950 text-slate-100 overflow-hidden">
            {/* Sidebar */}
            <aside className="w-64 border-r border-slate-800 flex flex-col bg-slate-900/50 backdrop-blur-xl">
                <div className="p-6 flex items-center gap-3">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center font-bold text-xl">C</div>
                    <span className="text-xl font-bold tracking-tight">CineFlow</span>
                </div>

                <nav className="flex-1 px-4 py-4 space-y-1">
                    <button 
                        onClick={() => setActiveTab('dashboard')}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-800 text-slate-400'}`}
                    >
                        <LayoutDashboard size={20} />
                        <span className="font-medium">Dashboard</span>
                    </button>
                    <button 
                        onClick={() => setActiveTab('inventory')}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'inventory' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-800 text-slate-400'}`}
                    >
                        <Box size={20} />
                        <span className="font-medium">Inventory</span>
                    </button>
                    <button 
                        onClick={() => setActiveTab('productions')}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'productions' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-800 text-slate-400'}`}
                    >
                        <ClipboardList size={20} />
                        <span className="font-medium">Productions</span>
                    </button>
                    <button 
                        onClick={() => setActiveTab('logs')}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'logs' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-800 text-slate-400'}`}
                    >
                        <Settings size={20} />
                        <span className="font-medium">Activity Logs</span>
                    </button>
                </nav>

                <div className="p-4 border-t border-slate-800">
                    <div className="flex items-center gap-3 p-3 rounded-xl hover:bg-slate-800/50 cursor-pointer">
                        <img src={user?.avatar_url} alt="Avatar" className="w-10 h-10 rounded-full border-2 border-indigo-500/30" />
                        <div className="flex-1 min-w-0">
                            <p className="text-sm font-semibold truncate">{user?.full_name}</p>
                            <p className="text-xs text-slate-500 uppercase tracking-wider font-bold">{user?.role}</p>
                        </div>
                        <LogOut size={16} className="text-slate-500 hover:text-red-400" />
                    </div>
                </div>
            </aside>

            {/* Main Content */}
            <main className="flex-1 overflow-y-auto custom-scrollbar relative">
                {/* Top Header */}
                <header className="sticky top-0 z-20 bg-slate-950/80 backdrop-blur-md border-b border-slate-800 px-8 py-4 flex items-center justify-between">
                    <div className="relative w-96">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
                        <input 
                            type="text" 
                            placeholder="Search inventory, serials, or crew..."
                            className="w-full bg-slate-900 border border-slate-700 rounded-full py-2 pl-10 pr-4 focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
