                                        }`}>
                                            {prod.status}
                                        </span>
                                    </div>
                                    <h3 className="text-xl font-bold mb-1">{prod.name}</h3>
                                    <p className="text-slate-400 text-sm mb-4">{prod.location}</p>
                                    <div className="flex items-center justify-between pt-4 border-t border-slate-800">
